const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '1/5' },
      { kind: 'text', payload: '2/5' },
      { kind: 'text', payload: '0' },
      { kind: 'text', payload: '1' },
      { kind: 'text', payload: '1/5 < 2/5' }
    ];
  },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var x0 = 70;
    var x1 = w - 70;
    var y0 = h * 0.52;
    var n = 5;
    var step = (x1 - x0) / n;
    var paths = [];
    var children = [];

    paths.push({ id: 'axis', commands: visualSdk.polyline([[x0, y0], [x1, y0]]) });
    children.push({ type: 'path', pathId: 'axis', fill: '#26354a', stroke: { width: 2 } });

    paths.push({ id: 'arrowHead', commands: visualSdk.polyline([[x1 - 12, y0 - 6], [x1, y0], [x1 - 12, y0 + 6]]) });
    children.push({ type: 'path', pathId: 'arrowHead', fill: '#26354a', stroke: { width: 2 } });

    for (var i = 0; i <= n; i++) {
      var x = x0 + i * step;
      var tid = 'tick' + i;
      paths.push({ id: tid, commands: visualSdk.polyline([[x, y0 - 7], [x, y0 + 7]]) });
      children.push({ type: 'path', pathId: tid, fill: '#26354a', stroke: { width: 2 } });
    }

    var dotIndices = [1, 2];
    for (var j = 0; j < dotIndices.length; j++) {
      var idx = dotIndices[j];
      var dx = x0 + idx * step;
      var did = 'dot' + idx;
      paths.push({ id: did, commands: visualSdk.circle(dx, y0, 5) });
      children.push({ type: 'path', pathId: did, fill: '#c0392b', stroke: { width: 2 } });
    }

    children.push({ type: 'label', contentId: 'c0', anchor: { x: x0 + step, y: y0 - 18 }, hAlign: 'center', vAlign: 'bottom', color: '#c0392b' });
    children.push({ type: 'label', contentId: 'c1', anchor: { x: x0 + 2 * step, y: y0 - 18 }, hAlign: 'center', vAlign: 'bottom', color: '#c0392b' });
    children.push({ type: 'label', contentId: 'c2', anchor: { x: x0, y: y0 + 20 }, hAlign: 'center', vAlign: 'top', color: '#26354a' });
    children.push({ type: 'label', contentId: 'c3', anchor: { x: x1, y: y0 + 20 }, hAlign: 'center', vAlign: 'top', color: '#26354a' });
    children.push({ type: 'label', contentId: 'c4', anchor: { x: (x0 + x1) / 2, y: y0 + 62 }, hAlign: 'center', vAlign: 'top', color: '#26354a' });

    return {
      schemaVersion: 1,
      sceneId: 'number-line-fifths',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
